import { handle, ConnectorConfig, StripeInvoicePayload } from './connector';
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      stripeWebhookSecret: 'whsec_test',
      quickbooksOAuthAccessToken: 'oauth_test_token',
      quickbooksCompanyId: '123456',
      defaultItemRef: { value: '1', name: 'Service' },
      defaultTaxCodeRef: { value: 'TAX' },
