describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    stripeWebhookSecret: 'whsec_test',
    quickbooksOAuthAccessToken: 'oauth_test_token',
    quickbooksCompanyId: '123456',
    defaultItemRef: { value: '1', name: 'Service' },
    defaultTaxCodeRef: { value: 'TAX' },
  };

  it('happy path creates invoice with correct request body and auth', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://quickbooks.api.intuit.com/v3/company/123456/invoice'
        ? jsonResponse({ Invoice: { Id: '789', SyncToken: '1' } }, 201)
        : jsonResponse({ error: 'not found' }, 404)
    );
    const payload: StripeInvoicePayload = {
      id: 'in_test123',
      url: 'https://pay.stripe.com/invoice/in_test123/hosted',
      lines: {
        data: [
          {
            id: 'li_1',
            description: 'Test item',
            amount: 2500,
            quantity: 2,
            discountable: false,
            tax_rates: [{ id: 'txr_1' }],
          },
        ],
      },
    };
    const result = await handle(payload, { ...baseConfig, fetch });
    expect(result.quickbooksInvoiceId).toBe('789');
    expect(result.lineItemCount).toBe(1);
    expect(calls).toHaveLength(1);
    const call = calls[0];
    expect(call.method).toBe('POST');
    expect(call.url).toBe('https://quickbooks.api.intuit.com/v3/company/123456/invoice');
    expect(call.headers.get('authorization')).toBe('Bearer oauth_test_token');
    expect(call.headers.get('content-type')).toBe('application/json');
    const body = call.json as { Line: unknown[]; CustomField: unknown[] };
    expect(body.Line).toHaveLength(1);
    const line = body.Line[0] as {
      Description: string;
      Amount: number;
      DetailType: string;
      SalesItemLineDetail: { ItemRef: { value: string; name: string }; UnitPrice: number; Qty: number; TaxCodeRef: { value: string } };
    };
    expect(line.Description).toBe('Test item');
    expect(line.Amount).toBe(50); // 2500 cents = 25.00 * qty 2 = 50
    expect(line.DetailType).toBe('SalesItemLineDetail');
    expect(line.SalesItemLineDetail.ItemRef).toEqual({ value: '1', name: 'Service' });
    expect(line.SalesItemLineDetail.UnitPrice).toBe(25);
    expect(line.SalesItemLineDetail.Qty).toBe(2);
    expect(line.SalesItemLineDetail.TaxCodeRef).toEqual({ value: 'TAX' });
    expect(body.CustomField).toHaveLength(1);
    expect(body.CustomField[0]).toEqual({
      DefinitionId: '1',
      StringValue: 'https://pay.stripe.com/invoice/in_test123/hosted',
    });
  });

  it('uses default quantity 1 when omitted', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      jsonResponse({ Invoice: { Id: '111', SyncToken: '0' } }, 201)
    );
    const payload: StripeInvoicePayload = {
      id: 'in_qty',
      url: 'https://pay.stripe.com/invoice/in_qty/hosted',
      lines: {
        data: [{ id: 'li_q', description: 'No qty', amount: 1000 }],
      },
    };
    await handle(payload, { ...baseConfig, fetch });
    const line = (calls[0].json as { Line: unknown[] }).Line[0] as { Qty: number };
    expect(line.Qty).toBe(1);
  });

  it('maps multiple line items in a single request', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      jsonResponse({ Invoice: { Id: '222', SyncToken: '0' } }, 201)
    );
    const payload: StripeInvoicePayload = {
      id: 'in_multi',
      url: 'https://pay.stripe.com/invoice/in_multi/hosted',
      lines: {
        data: [
          { id: 'li_a', description: 'Item A', amount: 1000 },
          { id: 'li_b', description: 'Item B', amount: 2000, quantity: 3 },
        ],
      },
    };
    const result = await handle(payload, { ...baseConfig, fetch });
    expect(result.lineItemCount).toBe(2);
    const lines = (calls[0].json as { Line: unknown[] }).Line;
    expect(lines).toHaveLength(2);
    expect((lines[0] as { Description: string }).Description).toBe('Item A');
    expect((lines[1] as { Description: string }).Description).toBe('Item B');
  });

  it('uses custom field definition id from config', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      jsonResponse({ Invoice: { Id: '333', SyncToken: '0' } }, 201)
    );
    const payload: StripeInvoicePayload = {
      id: 'in_custom',
      url: 'https://pay.stripe.com/invoice/in_custom/hosted',
      lines: { data: [{ id: 'li_c', description: 'Custom', amount: 500 }] },
    };
    await handle(payload, { ...baseConfig, quickbooksCustomFieldDefinitionId: '42', fetch });
    const custom = (calls[0].json as { CustomField: unknown[] }).CustomField[0] as { DefinitionId: string };
    expect(custom.DefinitionId).toBe('42');
  });

  it('throws on missing required field id', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { url: 'https://example.com', lines: { data: [] } } as unknown as StripeInvoicePayload;
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: id');
  });

  it('throws on missing required field url', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { id: 'in_1', lines: { data: [] } } as unknown as StripeInvoicePayload;
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: url');
  });

  it('throws on missing lines.data', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { id: 'in_1', url: 'https://example.com' } as unknown as StripeInvoicePayload;
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: lines.data');
  });

  it('throws when line item missing id', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload: StripeInvoicePayload = {
      id: 'in_1',
      url: 'https://example.com',
      lines: { data: [{ description: 'test', amount: 100 }] },
    };
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('lines.data[0].id is required');
  });

  it('throws when line item missing description', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload: StripeInvoicePayload = {
      id: 'in_1',
      url: 'https://example.com',
      lines: { data: [{ id: 'li_1', amount: 100 }] },
    };
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('lines.data[0].description is required');
  });

  it('throws when line item amount is not a finite number', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload: StripeInvoicePayload = {
      id: 'in_1',
      url: 'https://example.com',
      lines: { data: [{ id: 'li_1', description: 'test', amount: NaN }] },
    };
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('lines.data[0].amount must be a finite number');
  });

  it('throws on non-2xx response with status and endpoint', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));
    const payload: StripeInvoicePayload = {
      id: 'in_1',
      url: 'https://example.com',
      lines: { data: [{ id: 'li_1', description: 'test', amount: 100 }] },
    };
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'QuickBooks API error: 401 Unauthorized for POST https://quickbooks.api.intuit.com/v3/company/123456/invoice'
    );
  });

  it('throws when response missing Invoice.Id', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ Invoice: { SyncToken: '0' } }, 200));
    const payload: StripeInvoicePayload = {
      id: 'in_1',
      url: 'https://example.com',
      lines: { data: [{ id: 'li_1', description: 'test', amount: 100 }] },
    };
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('QuickBooks response missing Invoice.Id');
  });

  it('throws when fetch is not provided', async () => {
    const payload: StripeInvoicePayload = {
      id: 'in_1',
      url: 'https://example.com',
      lines: { data: [{ id: 'li_1', description: 'test', amount: 100 }] },
    };
    const config = { ...baseConfig, fetch: undefined as unknown as typeof fetch };
    await expect(handle(payload, config)).rejects.toThrow('fetch implementation is required');
  });
});

